<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<div class="wrap wpep-wrap" dir="rtl"><div class="wpep-card"><div class="wpep-card__head"><div><h1 class="wpep-card__title"><span class="dashicons dashicons-editor-help"></span> سوالات متداول</h1><p class="wpep-card__hint">پاسخ سوالات پرتکرار را قبل از ثبت تیکت به کاربر نشان دهید.</p></div></div><form method="post" class="jarchi-faq-admin-form"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr( wp_create_nonce( 'jarchi_faq_save' ) ); ?>"><div id="jarchi-faq-admin-list"><?php foreach ( (array) $settings['faq'] as $i => $item ) : ?><div class="jarchi-faq-admin-item"><input name="faq_title[]" value="<?php echo esc_attr( $item['title'] ?? '' ); ?>" placeholder="سوال"><textarea name="faq_body[]" rows="4" placeholder="پاسخ"><?php echo esc_textarea( $item['body'] ?? '' ); ?></textarea><button type="button" class="button jarchi-faq-remove">حذف</button></div><?php endforeach; ?></div><button type="button" class="button" id="jarchi-faq-add">+ افزودن سوال</button><p><button class="wpep-primary-button" name="jarchi_faq_save" value="1">ذخیره سوالات متداول</button></p></form></div></div><script>(function(){var list=document.getElementById("jarchi-faq-admin-list"),add=document.getElementById("jarchi-faq-add");function wire(){document.querySelectorAll(".jarchi-faq-remove").forEach(function(b){b.onclick=function(){b.closest(".jarchi-faq-admin-item").remove();};});}add&&add.addEventListener("click",function(){var d=document.createElement("div");d.className="jarchi-faq-admin-item";d.innerHTML="<input name=\"faq_title[]\" placeholder=\"سوال جدید\"><textarea name=\"faq_body[]\" rows=\"4\" placeholder=\"پاسخ\"></textarea><button type=\"button\" class=\"button jarchi-faq-remove\">حذف</button>";list.appendChild(d);wire();});wire();})();</script>